from astropy.coordinates import Angle

# Example 1: Angle("1d2m59.49999s").to_string(precision=0)
try:
    result = Angle("1d2m59.49999s").to_string(precision=0)
    probe('Angle("1d2m59.49999s").to_string(precision=0)', result)
except Exception as e:
    probe('Angle("1d2m59.49999s").to_string(precision=0)', "__error__: " + type(e).__name__ + ": " + str(e))

